function validate(data){
 var errors=[];
 if(!Array.isArray(data)||data.length!==15) errors.push("weeks must contain exactly 15 entries");
 (data||[]).forEach(function(w,i){
  if(!w||w.id!=="w"+(i+1)||w.week!==i+1) errors.push("week "+(i+1)+" id/number mismatch");
  ["title","chapter","artifact","summary"].forEach(function(k){if(!w[k]) errors.push((w.id||i)+"."+k+" missing");});
  if(!Array.isArray(w.fields)||w.fields.length<3||w.fields.length>5) errors.push((w.id||i)+".fields must contain 3-5 entries");
  if(!Array.isArray(w.scenarios)||w.scenarios.length!==2) errors.push((w.id||i)+".scenarios must contain 2 entries");
  (w.scenarios||[]).forEach(function(s){
   if(!Array.isArray(s.evidence)||s.evidence.length<2) errors.push(w.id+"/"+s.id+" evidence missing");
   var evidenceIds=new Set((s.evidence||[]).map(function(e){return e.id;}));
   if(!Array.isArray(s.steps)||s.steps.length!==3) errors.push(w.id+"/"+s.id+" steps must contain 3");
   (s.steps||[]).forEach(function(st){
    var options=st.options||[];
    var scores=options.map(function(o){return o.score;}).sort(function(a,b){return a-b;});
    if(options.length!==3||scores.join(",")!=="0,1,2") errors.push(w.id+"/"+s.id+"/"+st.id+" scores must be 0,1,2");
    var best=options.filter(function(o){return o.score===2;});
    if(best.length!==1||st.bestId!==best[0].id) errors.push(w.id+"/"+s.id+"/"+st.id+" bestId mismatch");
    options.forEach(function(o){
     if(!o.why||!/\[[^\]]+\]/.test(o.why)) errors.push(w.id+"/"+s.id+"/"+st.id+"/"+o.id+" missing evidence ref");
     var refs=(o.why.match(/\[([^\]]+)\]/g)||[]).map(function(x){return x.slice(1,-1);});
     refs.forEach(function(ref){if(!evidenceIds.has(ref)) errors.push(w.id+"/"+s.id+"/"+st.id+" unknown evidence "+ref);});
    });
   });
  });
 });
 return {ok:errors.length===0,errors:errors};
}
